&=& - \frac{1}{2}  \sigma^2  u^2 - \sigma^2 K u -  \beta  u  \\
u' &=&  - \frac{1}{2}  \sigma^2  u^2 - \sigma^2 K u -  \beta  u  
\end{eqnarray} 
 Let  $u=1/z$ . Besides,  $u'=-z'/z^2$ .
 \begin{eqnarray}
u' &=&  - \frac{1}{2}  \sigma^2  u^2 - \sigma^2 K u -  \beta  u \\
-\frac{z'}{z^2} &=& - \frac{1}{2}  \sigma^2 \frac{1}{z^2} - (  \sigma^2 K  +  \beta ) \frac{1}{z} \\
z' &=&  \frac{\sigma^2}{2} +  (  \sigma^2 K  +  \beta ) z
\end{eqnarray} 
 Let  $M=\sigma^2/2$  and  $N= (  \sigma^2 K +  \beta ) $ . Therefore, with Integral constant  $C$ ,
