= \frac{C N K e^{Nt} - KM +N}{C N e^{Nt} - M} 
\end{eqnarray} 
 Let  $t=0$ , since  $B=0$ .
 \begin{eqnarray}
&& \frac{C N K e^{0} - KM +N}{C N e^{0} - M} = 0 \\
&& \frac{C N K  - KM +N}{C N  - M} = 0
\end{eqnarray} 
